+  chmodSync(dir, 0o700);
+  const path = join(dir, name);
+  writeFileSync(path, typeof value === "string" ? value : JSON.stringify(value), { mode: 0o600 });
+  chmodSync(path, 0o600);
+  utimesSync(path, new Date(NOW - 1_000), new Date(NOW - 1_000));
+  return path;
+}
