+    XDG_STATE_HOME: join(root, "state"),
+    XDG_RUNTIME_DIR: join(root, "runtime"),
+    TMPDIR: join(root, "tmp"),
+    TMUX_TMPDIR: join(root, "tmux"),
+    TMUX: join(root, "tmux.sock") + ",1,0",
+    TMUX_PANE: "%worker",
+    MOCK_SESSION: "$worker",
+    MOCK_PANE: "%worker",
+    TMUX_CALLS: calls,
+    XTMUX_HOST_ID: "test-host",
+    XTMUX_OBS_V2: "1",
+    XTMUX_OBS_V2_REPO: ROOT,
